mapper.sql:
FROM "bus_stops" "bs"
JOIN "agencies" "a"
ON "a"."del_flag"                = 0
AND "a"."available_flag"          = 1
AND "a"."business_corp_id"        = "bs"."business_corp_id"
WHERE "bs"."del_flag"               = 0
AND "a"."business_corp_id"        = #{businessCorpId}

    AND "bs"."bus_stop_name"       LIKE #{likeSearchBusStopName}


    AND "bs"."bus_stop_code"          = #{busStopCode}


    AND "bs"."service_start_date" <= CAST(#{serviceEndDate} AS date)


    AND "bs"."service_end_date"    >= CAST(#{serviceStartDate} AS date)


    AND "bs"."available_flag"          = #{searchUsageDivision}

mapper.insert:
INSERT INTO "bus_stops" (
"business_corp_id"
, "bus_stop_code"
, "service_start_date"
, "service_end_date"
, "bus_stop_name"
, "bus_stop_kana_name"
, "bus_stop_en_name"
, "bus_stop_url"
, "bus_stop_type"
, "available_flag"

    , "latitude_longitude"

, "indoor_bus_terminal_flag"

)
VALUES (
#{session.businessCorpId}
, #{busStopCode}
, CAST(#{serviceStartDate} AS date)
, CAST(#{serviceEndDate} AS date)
, #{busStopName}
, #{busStopKanaName}
, #{busStopEnName}
, #{busStopUrl}
, #{busStopType}
, #{availableFlag}

    , #{latitudeLongitude}

, #{indoorBusTerminalFlag}

)

mapper.update:
UPDATE "bus_stops"
SET "bus_stop_code"      = #{busStopCode}
, "service_start_date" = CAST(#{serviceStartDate} AS date)
, "service_end_date"   = CAST(#{serviceEndDate} AS date)
, "bus_stop_name"      = #{busStopName}
, "bus_stop_kana_name" = #{busStopKanaName}
, "bus_stop_en_name"   = #{busStopEnName}
, "bus_stop_url"       = #{busStopUrl}
, "available_flag"     = #{availableFlag}


        , "latitude_longitude" = #{latitudeLongitude}


        , "latitude_longitude" = NULL


, "indoor_bus_terminal_flag" = #{indoorBusTerminalFlag}

WHERE "del_flag"            = 0
AND "bus_stop_id"         = #{busStopId}

mapper.select:
SELECT "bs"."bus_stop_id" , "bs"."bus_stop_code" , "bs"."service_start_date" , "bs"."service_end_date" , "bs"."bus_stop_name" , "bs"."bus_stop_kana_name" , "bs"."bus_stop_en_name" , "bs"."latitude_longitude" FROM "bus_stops" "bs" JOIN "agencies" "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "a"."business_corp_id" = "bs"."business_corp_id" WHERE "bs"."del_flag" = 0 AND "bs"."available_flag" = 1 AND "bs"."business_corp_id" = #{businessCorpId}
AND "bs"."service_start_date" <= CAST(#{serviceEndDate} AS date)
AND "bs"."service_end_date" >= CAST(#{serviceStartDate} AS date)

mapper.insert:
INSERT INTO "bus_stops" ( "business_corp_id" , "bus_stop_code" , "service_start_date" , "service_end_date" , "bus_stop_name" , "bus_stop_kana_name" , "bus_stop_en_name" , "bus_stop_url" , "bus_stop_type" , "available_flag" , "latitude_longitude" , "indoor_bus_terminal_flag"
) VALUES ( CAST(#{businessCorpId} AS INTEGER), #{busStopCode}, CAST(#{serviceStartDate} AS DATE), CAST(#{serviceEndDate} AS DATE), COALESCE(#{busStopName}, ''), COALESCE(#{busStopKanaName}, ''), COALESCE(#{busStopEnName}, ''), COALESCE(#{busStopUrl}, ''), 1, 1, COALESCE(#{latitudeLongitude}, '0.0,0.0'), CAST(COALESCE(#{indoorBusTerminalFlag}, '0') AS SMALLINT)
)
